#!/usr/bin/env python3
"""QA14 packet assembly only. Reads published evidence and executed QA payloads.
Never imports production or original CLR code; writes only this QA14 directory.
"""
import base64
from collections import Counter
import gzip
import hashlib
import json
from pathlib import Path
import sys

QA=Path(__file__).resolve().parent
ROOT=QA.parents[2]
V=QA/'verification'
def sha(b):return hashlib.sha256(b).hexdigest()
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
def raw(p):
    p=Path(p)
    if p.exists():return p.read_bytes()
    return gzip.decompress(base64.b64decode(Path(str(p)+'.gz.b64').read_bytes()))
def load(p):return json.loads(raw(p))

def pack():
    manifest=load(V/'packed-files.json') if (V/'packed-files.json').exists() else {}
    for p in sorted(V.rglob('*')):
        if not p.is_file() or p.suffix not in ['.json','.log']:continue
        if p.name in ['baseline.json','packed-files.json'] or p.stat().st_size<100000 and p.suffix!='.log':continue
        b=p.read_bytes();z=gzip.compress(b,mtime=0);target=Path(str(p)+'.gz.b64')
        target.write_bytes(base64.b64encode(z)+b'\n')
        assert gzip.decompress(base64.b64decode(target.read_bytes()))==b
        manifest[str(p.relative_to(QA)).replace('\\','/')]={'stored':str(target.relative_to(QA)).replace('\\','/'),'bytes':len(b),'sha256':sha(b),'compression':'gzip/base64 lossless; original bytes retained'}
        p.unlink()
    write(V/'packed-files.json',manifest)

def fixtures():
    records={p.name:{'bytes':len(p.read_bytes()),'sha256':sha(p.read_bytes()),'canonicalLFsha256':sha(p.read_bytes().replace(b'\r\n',b'\n'))} for p in sorted((QA/'Inputs').glob('*.osu'))}
    write(QA/'Inputs/manifest.json',{'schema':'QA14.fixture.v1','files':records,'recipes':'Large file/count/depth/junction fixtures are generated by the named Headless controls; no original map or proprietary asset data.'})

def ci(log_path,run_path):
    b=Path(log_path).read_bytes();text=b.decode('utf-8-sig')
    found={}
    for label,name in [('QA14','windows-results.json'),('QA14 WINDOWS','windows-widget-results.json')]:
        marker=label+' EVIDENCE '
        lines=[line.split(marker,1)[1].strip() for line in text.splitlines() if marker in line]
        assert len(lines)==1,(label,len(lines))
        data=gzip.decompress(base64.b64decode(lines[0]));j=json.loads(data)
        (V/name).write_bytes(data)
        found[label]={'bytes':len(data),'sha256':sha(data),'source':j['source'],'named':j['named'],'passed':j['passed'],'failed':j['failed']}
    (V/'windows-job-original.log').write_bytes(b)
    run=json.loads(Path(run_path).read_text(encoding='utf-8-sig'))
    write(V/'windows-run.json',run)
    write(V/'windows-provenance.json',{'source':run['headSha'],'run':run['databaseId'],'url':run['url'],'conclusion':run['conclusion'],'returnedLog':{'bytes':len(b),'sha256':sha(b)},'packets':found})
    print(json.dumps(found,indent=2))

def coverage():
    original=load(ROOT/'re/evidence/43/selectplay.json')
    head=load(V/'windows-results.json');windows=load(V/'windows-widget-results.json')
    cases={c['id']:(c,'windows-results.json') for c in head['cases']}
    cases.update({c['id']:(c,'windows-widget-results.json') for c in windows['cases']})
    finite={9,10,11,14,16,17,18,19,20,29,31,32,33,34,36,37,50,51,57}
    unsupported=set(range(1,9))|{22,23,24,25,39,45,46,47,48,49,55,56,58,59,60,61,66}
    bindings={
        9:['G/one','W05'],10:['G/one-folder','G/row-indexes'],11:['G/interleaved'],
        12:['S/same-run','S/row-before','W14'],13:['S/different-run'],14:['S/same-reference'],15:['S/cleanup-before'],16:['S/cleanup-throws'],17:['S/null-retains'],18:['S/row-before'],19:['S/different-run','W04'],20:['S/rebuild-missing','W21'],
        21:['I/delete','I/path-replaced'],26:['C/one','C/external-path'],27:['S/callback-throws-after','R/index-is-not-parser'],28:['C/superseded','S/stale-generation','W16'],29:['S/live-selection-after-rebuild'],30:['E/accepted','E/duplicate','A/queued-host'],31:['E/no-selection'],32:['E/temporary'],33:['E/phase-1'],34:['R/missing-before-request'],35:['E/accepted','A/queued-host'],36:['E/live-before-capture'],37:['E/after-capture-retained','P/retry-captured'],38:['W24','A/refresh-back'],40:['P/rank-return-unchanged','W20'],41:['P/rank-return-deleted','P/rank-return-changed','W21','S/return-after-cancelled'],42:['M/all-text','M/counts','M/base-bpm','M/scalars'],43:['M/changed-display','S/new-revision'],44:['M/unicode'],50:['M/no-gameplay','P/matched-'],51:['T/value-ordinary','T/value-below-decimal','T/value-one-cent'],52:['T/no-cache','W13'],53:['T/value-negative','T/value-explicit-stale'],54:['T/nan'],57:['T/mods-'],62:['S/confirmation','W05','W06','A/browser-rank'],63:['S/mouse','W07','A/windows-view'],64:['W10','A/refresh-back'],65:['W17','W18','E/disposed','A/refresh-back']}
    scopes={
        12:'Reference update/order exercised; original preview/resource cleanup not reproduced.',13:'Different-run commit exercised; original select-expand sound/preview excluded.',15:'Injected cleanup-before-store exercised; original M1c12/M38b9 resources excluded.',21:'Deletion/revision refresh exercised; original watcher/F0fde scan policy excluded.',26:'Local discovery/index exercised; original F1a0b queue and parser not implemented.',27:'Post-store failure containment exercised; original repair UI/preview excluded.',28:'Generation rejection exercised; original active-object identity worker guards not reproduced.',30:'Actual production stages and host source order checked; original cleanup resources/scheduler excluded.',35:'No request-time chart payload checked; original queue/native commitment unmeasured.',38:'Actual R15 Rank Back component exercised; original menuback and mode manager excluded.',40:'Available selected reference/group restored; original saved search/ruleset/native scroll excluded.',41:'Explicit missing/revision recovery exercised; original constructor fallback branches not reproduced.',42:'Prepared engineering display fields exercised; original localized/native widgets and exact BPM policy excluded.',43:'Changed metadata/revision exercised; original star background worker excluded.',44:'Unicode preference/fallback exercised; original cached-header getter not reproduced.',52:'Engineering no-cache message verified; original zero/default and calculation request deliberately not implemented.',53:'Negative magnitude/stale display exercised; original in-progress refresh worker excluded.',54:'Nonfinite unavailable policy exercised; original display/refresh predicates not identical.',62:'Actual model/view confirmation plus source key audit; no physical key or original dispatcher.',63:'Actual view callback exercised; mouse-down engineering bridge differs from original release/geometry.',64:'Back callback exercised; Local Practice Home is an engineering substitute for Menu0.',65:'Supported public callbacks/disposal/subscription checked; original scheduler and retained visual containers excluded.'}
    rows=[]
    for n,old in enumerate(original['reference_cases'],1):
        classification='FINITE' if n in finite else 'UNSUPPORTED' if n in unsupported else 'PARTIAL'
        matches=sorted({k for prefix in bindings.get(n,[]) for k in cases if k.startswith(prefix)})
        inputs=[]
        for key in matches:
            case,packet=cases[key]
            packet_path=V/packet
            if not packet_path.exists():packet_path=Path(str(packet_path)+'.gz.b64')
            assert packet_path.exists()
            inputs.append({'control':key,'packet':str(packet_path.relative_to(QA)).replace('\\','/'),'classification':case['classification'],'passed':case['passed'],'caseSha256':sha(json.dumps(case,sort_keys=True,ensure_ascii=False).encode()),'expectedActual':'See the retained observations/input fixtures in this exact control, not a development-suite expected value.'})
        if classification!='UNSUPPORTED':assert inputs,old['id']
        if any(not c['passed'] for c in inputs):classification='DISCREPANCY'
        scope=scopes.get(n,'Finite supported production projection of the cited E043 reference/dataflow predicate; injected operands do not establish original execution.' if classification=='FINITE' else 'Original mode manager/loading19/database/filename comparator/preview/star-worker/profile/native dependency excluded by R16; no substitute is counted as original coverage.')
        rows.append({'id':old['id'],'originalEvidence':old['evidence'],'originalInitial':old['initial_state'],'originalStaticPrediction':old['expected'],'classification':classification,'productionBoundary':'Selection/LocalChartCatalog.cs, SelectPlayModel.cs; Rendering/SelectPlayView.cs; existing Rank/parser/kernel; Program host as source audit only','scope':scope,'inputsAndOutcomes':inputs,'engineeringSubstitution':'Canonical path/revision identity, invariant WPF display, scan limits, generation cancellation, silent selection and supplied-cache admission are explicitly engineering. SelectedChartState.Set combines the M2581 null guard with bounded M2c64-like reference/store behavior; raw original M2c64(null) is not claimed.','originalCaseExecuted':False,'originalRuntime':'UNVERIFIED ORIGINAL-RUNTIME','discrepancy':None if classification!='DISCREPANCY' else 'Retained failed control; requires review without production repair.'})
    write(QA/'e043-coverage.json',{'schema':'QA14.E043.coverage.v1','authoritySha256':sha(raw(ROOT/'re/evidence/43/selectplay.json')),'testedSource':head['source'],'rows':rows,'counts':dict(Counter(r['classification'] for r in rows)),'rule':'66 matrix rows are not66 extra tests. FINITE means executed bounded reconstruction projection, never original runtime. This matrix was independently bound to QA14 controls, not R16 development expectations.'})
    print('matrix',Counter(r['classification'] for r in rows))

if __name__=='__main__':
    if sys.argv[1]=='pack':pack()
    elif sys.argv[1]=='fixtures':fixtures()
    elif sys.argv[1]=='ci':ci(sys.argv[2],sys.argv[3]);pack()
    elif sys.argv[1]=='coverage':coverage()
    else:raise SystemExit('pack | fixtures | ci LOG RUNJSON | coverage')
